try {
  mkdirSync(join(dir, "docs", "story", "actives"), { recursive: true });
  writeFileSync(join(dir, "koala.config.json"), JSON.stringify({ scanRoot: "packages/main", rootDir: "src", outDir: "packages/main/dist", testsDir: "packages/main/tests", fixturesDir: "packages/main/tests/fixtures", storyDir: "docs/story/actives", requirementsDir: "docs/requirements", storyPrefix: "B" }, null, 2));
  git(dir, ["init"]); git(dir, ["config", "user.name", "Koala Test"]); git(dir, ["config", "user.email", "koala@example.com"]);
  writeFileSync(join(dir, ".gitignore"), "node_modules\n"); git(dir, ["add", "."]); git(dir, ["commit", "-m", "init"]);
  const store = new StoryStore(dir);
  store.writeStory("B-test", { storyId: "B-test", name: "x", title: "x", description: "x", type: "bug", phase: "DEV", priority: "high", createdAt: new Date().toISOString(), startedAt: new Date().toISOString(), endedAt: null, worktree: { path: ".worktrees/B-test", branch: "story/B-test", createdAt: new Date().toISOString() } });
  git(dir, ["add", "docs/story/actives"]); git(dir, ["commit", "-m", "story"]);
  const wt = join(dir, ".worktrees", "B-test");
  git(dir, ["worktree", "add", "-b", "story/B-test", wt]);
  writeFileSync(join(wt, "scratch.txt"), "change\n"); git(wt, ["add", "scratch.txt"]); git(wt, ["commit", "-m", "change"]);
  return { noZombie: detectZombieStories(store, dir).length === 0 };
} finally { rmSync(dir, { recursive: true, force: true }); }

